\title{Analogy as a Mathematical Operation: Metric Fidelity, Adjoint Structure, and Tropical Optimization}
\author{Aristotle}
\date{2026-07-12}

\begin{document}

\begin{abstract}
We develop a mathematical theory of \emph{analogy-making} inspired by Hofstadter's account of analogy as the core of cognition. An analogy between two structures $A$ and $B$ is formalized as a pair of maps $F : A \to B$ (forward) and $G : B \to A$ (backward), and the \emph{quality} of the analogy is measured by its \textbf{distortion} --- the largest displacement of a point under the round trip $G \circ F$. We prove that the identity (``copycat'') analogy achieves the minimum possible distortion of zero, that zero distortion exactly characterizes a perfect left inverse, and that distortion is monotone and non-negative. We establish a \emph{triangle inequality for analogies}: under a Lipschitz condition, distortions accumulate subadditively along a chain, $\varepsilon_f + L\varepsilon_g$. We disprove a natural but false conjecture --- a perfect one-directional analogy need not be an equivalence --- by an explicit collapse example. Modeling the canonical structure-preserving analogy between concept lattices as a Galois connection (an \textbf{adjoint analogy}), we show its round trips are monotone idempotent closure/kernel operators, that the backward map is uniquely determined by the forward map, and that the copycat is a rigid, self-dual adjoint. Finally, we cast ``making the best analogy'' as an optimization over a finite pool of candidate costs and prove that it is solved by a single operation in the \textbf{tropical (min-plus) semiring}: the tropical sum of candidate costs equals the optimal cost, is attained by a candidate, and lower-bounds all candidates.
\end{abstract}

\maketitle

\section{Introduction}
Hofstadter, in \emph{Fluid Concepts and Creative Analogies}, argues that analogy-making is the central mechanism of cognition. We ask a mathematical question suggested by that program: can analogy be treated as a mathematical operation with a measurable quality and a well-posed optimization? We answer affirmatively across three registers: a metric theory (Section~\ref{sec:metric}), an order-theoretic theory of adjoint analogies (Section~\ref{sec:adjoint}), and a tropical optimization (Section~\ref{sec:tropical}). We also record a cautionary negative result: perfect fidelity in one direction does not imply an equivalence.

\section{Preliminaries}
We work with (pseudo)metric spaces and preorders. For a pseudometric space $A$, $\dist(\cdot,\cdot)$ satisfies $\dist(x,x)=0$, symmetry, and the triangle inequality; a metric space additionally satisfies $\dist(x,y)=0 \Rightarrow x=y$. A map $h$ is \textbf{$L$-Lipschitz} if $\dist(h(x),h(y)) \le L\,\dist(x,y)$. The \textbf{tropical (min-plus) semiring} over $\Rinf := \mathbb{R}\cup\{+\infty\}$ uses $x\oplus y := \min(x,y)$ as addition (identity $+\infty$) and $+$ as multiplication.

\section{The metric theory of analogies}\label{sec:metric}

\begin{definition}[Analogy]
An \textbf{analogy} between structures $A$ and $B$ is a pair $f=(F,G)$ with $F:A\to B$ (forward) and $G:B\to A$ (backward). No compatibility is assumed a priori.
\end{definition}

\begin{definition}[Copycat and composition]
The \textbf{copycat analogy} $\id_A$ on $A$ has $A=B$ and $F=G=\id$. For $f=(F_f,G_f):A\to B$ and $g=(F_g,G_g):B\to C$, the composite is $g\circ f := (F_g\circ F_f,\ G_f\circ G_g)$.
\end{definition}

\begin{definition}[Distortion and fidelity]
Let $A$ be a pseudometric space and $f=(F,G)$ an analogy from $A$ to $B$. Then $f$ has \textbf{fidelity} $\varepsilon\in\mathbb{R}$ if $\dist(a, G(F(a)))\le\varepsilon$ for all $a\in A$. The \textbf{distortion} of $f$ is the least such $\varepsilon$.
\end{definition}

\begin{theorem}[Copycat fidelity]
The copycat analogy $\id_A$ has fidelity $0$.
\end{theorem}
\begin{proof}
The round trip is $\id$, so $\dist(a,a)=0\le 0$.
\end{proof}

\begin{theorem}[Non-negativity]
If $A$ is nonempty and $f$ has fidelity $\varepsilon$, then $\varepsilon\ge 0$.
\end{theorem}
\begin{proof}
For any $a\in A$, $0\le \dist(a,G(F(a)))\le\varepsilon$.
\end{proof}

\begin{theorem}[Monotonicity]
If $\varepsilon\le\varepsilon'$ and $f$ has fidelity $\varepsilon$, then $f$ has fidelity $\varepsilon'$.
\end{theorem}
\begin{proof}
$\dist(a,G(F(a)))\le\varepsilon\le\varepsilon'$ for each $a$.
\end{proof}

\begin{theorem}[Fidelity-zero characterization]
Let $A$ be a metric space and $f=(F,G)$ an analogy from $A$ to $B$. Then $f$ has fidelity $0$ iff $G(F(a))=a$ for all $a\in A$.
\end{theorem}
\begin{proof}
($\Rightarrow$) $\dist(a,G(F(a)))\le 0$ forces $=0$, hence $G(F(a))=a$. ($\Leftarrow$) $\dist(a,a)=0\le 0$.
\end{proof}

\begin{theorem}[Composition bound]\label{thm:comp}
Let $A,B$ be pseudometric spaces, $f:A\to B$ with fidelity $\varepsilon_f$, $g:B\to C$ with fidelity $\varepsilon_g$, and $G_f$ being $L$-Lipschitz with $L\ge 0$. Then $g\circ f$ has fidelity $\varepsilon_f + L\,\varepsilon_g$.
\end{theorem}
\begin{proof}
Fix $a$, set $b:=F_f(a)$. The round trip sends $a$ to $G_f(G_g(F_g(b)))$. By the triangle inequality,
\[
\dist(a, G_f(G_g(F_g(b)))) \le \dist(a,G_f(b)) + \dist(G_f(b), G_f(G_g(F_g(b)))).
\]
The first term is $\le\varepsilon_f$; for the second, $L$-Lipschitzness of $G_f$ and fidelity of $g$ give $\le L\,\dist(b,G_g(F_g(b)))\le L\varepsilon_g$. Sum to conclude.
\end{proof}

\begin{corollary}[Chains stay good]
A composite $f_n\circ\cdots\circ f_1$ with fidelities $\varepsilon_i$ and backward Lipschitz constants $L_i$ has fidelity bounded by $\varepsilon_1 + L_1\varepsilon_2 + L_1L_2\varepsilon_3 + \cdots$.
\end{corollary}

\begin{theorem}[Collapse counterexample]
There is an analogy $f=(F,G)$ from $A=\{\ast\}$ to $B=\mathbb{R}$ with fidelity $0$, yet $F(G(1))\ne 1$.
\end{theorem}
\begin{proof}
Let $F(\ast)=0$ and $G(x)=\ast$. Then $G(F(\ast))=\ast$, so fidelity $0$; but $F(G(1))=F(\ast)=0\ne 1$.
\end{proof}

\section{The adjoint (Galois) model on concept lattices}\label{sec:adjoint}

\begin{definition}[Adjoint analogy]
Let $(L,\le),(M,\le)$ be preorders. An \textbf{adjoint analogy} is a pair $l:L\to M$, $u:M\to L$ forming a Galois connection: $l(a)\le b \iff a\le u(b)$ for all $a,b$.
\end{definition}

\begin{theorem}[Extensivity]
For an adjoint analogy and every $a$, $a\le u(l(a))$.
\end{theorem}
\begin{proof}
Apply the equivalence to $b=l(a)$ using $l(a)\le l(a)$.
\end{proof}

\begin{theorem}[Closure operator]
If $L$ is a partial order, $u\circ l$ is idempotent: $u(l(u(l(a))))=u(l(a))$.
\end{theorem}
\begin{proof}
Standard $u\,l\,u=u$ identity; $u\circ l$ is extensive, monotone, and idempotent, hence a closure operator.
\end{proof}

\begin{theorem}[Kernel operator]
If $M$ is a partial order, $l\circ u$ is idempotent: $l(u(l(u(b))))=l(u(b))$.
\end{theorem}
\begin{proof}
Dual, using $l\,u\,l=l$.
\end{proof}

\begin{theorem}[Monotone round trip]
$u\circ l$ is monotone.
\end{theorem}
\begin{proof}
Both adjoints are monotone; composition preserves monotonicity.
\end{proof}

\begin{theorem}[Uniqueness of the adjoint]\label{thm:unique}
Let $L,M$ be partial orders. If $l\dashv u_1$ and $l\dashv u_2$, then $u_1=u_2$.
\end{theorem}
\begin{proof}
Fix $b$. From $l(u_1(b))\le b$ and the second connection, $u_1(b)\le u_2(b)$; symmetrically $u_2(b)\le u_1(b)$. Antisymmetry gives equality.
\end{proof}

\begin{theorem}[Copycat is adjoint]
On any preorder $L$, $(\id_L,\id_L)$ is an adjoint analogy.
\end{theorem}
\begin{proof}
$\id(a)\le b \iff a\le\id(b)$ is $a\le b\iff a\le b$.
\end{proof}

\begin{theorem}[Copycat rigidity]
On a partial order $L$, if $\id_L\dashv u$, then $u=\id_L$.
\end{theorem}
\begin{proof}
$\id_L$ is an adjoint of $\id_L$; by Theorem~\ref{thm:unique}, $u=\id_L$.
\end{proof}

\section{Making the best analogy: a tropical optimization}\label{sec:tropical}

\begin{definition}[Candidate pool]
A \textbf{candidate pool} is a finite index set $s$ with a \textbf{cost} $\operatorname{cost}:s\to\Rinf$, where $+\infty$ marks infeasibility. The \textbf{best analogy} minimizes $\operatorname{cost}$ over $s$.
\end{definition}

\begin{theorem}[Existence]
Over a nonempty finite pool with real costs, there is $i\in s$ with $\operatorname{cost}(i)\le\operatorname{cost}(j)$ for all $j\in s$.
\end{theorem}
\begin{proof}
A real-valued function on a nonempty finite set attains its minimum.
\end{proof}

\begin{definition}[Tropical score]
$\Score(s,\operatorname{cost}) := \bigoplus_{i\in s}\operatorname{cost}(i)$, with $x\oplus y=\min(x,y)$ and empty sum $+\infty$.
\end{definition}

\begin{theorem}[Tropical sum is the minimum]
$\Score(s,\operatorname{cost}) = \inf_{i\in s}\operatorname{cost}(i)$.
\end{theorem}
\begin{proof}
Tropical addition is $\min$; a finite tropical sum is the iterated minimum, i.e. the finite infimum.
\end{proof}

\begin{theorem}[Lower bound]
For every $j\in s$, $\Score(s,\operatorname{cost})\le\operatorname{cost}(j)$.
\end{theorem}
\begin{proof}
The infimum lower-bounds each element.
\end{proof}

\begin{theorem}[Attainment]
Over a nonempty pool, there is $i\in s$ with $\Score(s,\operatorname{cost})=\operatorname{cost}(i)$.
\end{theorem}
\begin{proof}
The finite infimum over a nonempty set is attained.
\end{proof}

\begin{theorem}[The tropical sum is the best analogy's cost]
Over a nonempty finite pool,
\[
\big(\exists\, i\in s:\ \Score(s,\operatorname{cost})=\operatorname{cost}(i)\big)\ \wedge\ \big(\forall\, j\in s:\ \Score(s,\operatorname{cost})\le\operatorname{cost}(j)\big).
\]
\end{theorem}
\begin{proof}
Combine attainment and the lower bound.
\end{proof}

\section{Discussion and future directions}
The theory isolates a quantitative facet (distortion, with a compositional error calculus), a structural facet (Galois adjunction, with rigidity and uniqueness), and a computational facet (tropical optimization). Open threads: (1) the sharp constant in Theorem~\ref{thm:comp}; (2) a bidirectional distortion $\max(\sup_a \dist(a,G(F(a))), \sup_b \dist(b,F(G(b))))$ characterizing genuine isometric analogies; (3) optimal analogies over infinite pools via lower semicontinuity; (4) a richer idempotent-algebraic model of creative reasoning.

\end{document}

