from math import inf
from typing import Sequence

def tropical_sum(values: Sequence[float]) -> float:
    """Min-plus sum: identity +inf, x (+) y = min(x, y)."""
    total = inf
    for v in values:
        total = min(total, v)
    return total

def best_analogy(costs: dict[str, float]) -> tuple[str, float]:
    name, best = None, inf
    for k, v in costs.items():
        if v < best:
            name, best = k, v
    return name, best

if __name__ == "__main__":
    costs = {"solar-system": 0.90, "water-in-pipes": 0.35,
             "billiard-balls": 0.60, "infeasible": inf}
    score = tropical_sum(list(costs.values()))
    name, cost = best_analogy(costs)
    print("tropical score =", score, "| best =", name, cost)
    print("score == best cost:", abs(score - cost) < 1e-12)
    print("score lower-bounds all:", all(score <= v + 1e-12 for v in costs.values()))

