function BEST_ANALOGY_TROPICAL(candidates):
    best_key  <- undefined
    best_cost <- +infinity            # tropical zero
    for (key, cost) in candidates:
        best_cost <- min(best_cost, cost)   # tropical addition
        if cost == best_cost:
            best_key <- key
    if best_key is undefined: error 'empty pool'
    return (best_key, best_cost)

function CONSTRUCT_AND_VERIFY_ADJOINT(L, M, l, le_L, le_M):
    for b in M:
        below <- { a in L : le_M(l(a), b) }
        if below is empty: return NONE
        cand <- a greatest element of below under le_L
        if no greatest element exists: return NONE
        u[b] <- cand
    if for all a,b:  le_M(l(a),b) == le_L(a, u[b]):
        return u
    else:
        return NONE

